/*!
 * CounterUp 1.0
 */
(function($){"use strict";$.fn.counterUp=function(options){var settings=$.extend({time:400,delay:10},options);return this.each(function(){var $this=$(this);var counter=function(){var nums=[];var isComma=/[0-9]+,[0-9]+/.test($this.text());$this.text($this.text().replace(/,/g,''));var num=$this.text();var numParts=num.split('.');var isFloat=numParts.length>1;var decimal='';if(isFloat){decimal='.'+numParts[1]}num=numParts[0];var numLength=num.length;for(var i=numLength;i>=1;i--){nums.unshift(num.substr(0,i))}var f=function(){if(nums.length){$this.text(nums.shift()+decimal);setTimeout(f,settings.delay)}else{$this.text(num+decimal)}};setTimeout(f,settings.time)};$this.waypoint(function(){counter();this.destroy()},{offset:'100%'})})}})(jQuery);
